INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'RealHelp', NULL, 'https://realhelp.me', NULL, NULL, 'Соціальна мережа для благодійності: допомога верифікованим людям у скруті зі звітами про кожен донат.', 'A social network for charity: help verified people in hardship, with a report for every donation.', 'RealHelp поєднує тих, хто хоче допомогти, з людьми, які потребують підтримки. Профілі отримувачів верифіковані, кожен донат відстежується і підтверджується звітом. Можна допомагати анонімно або оформити щомісячну підписку.', 'RealHelp connects people who want to help with those who need support. Recipient profiles are verified, and every donation is tracked and confirmed by a report. You can give anonymously or set up a monthly subscription.', 'Верифіковані профілі отримувачів
