SET NAMES utf8mb4;

-- =====================================================================
-- AI LAB HUB — партія 2026-10-28: категорія «Українські додатки» / «Ukrainian Apps» (slug ukrainian-apps) з підкатегоріями:
--   * Державні послуги / Government Services (slug ua-gov)
--   * Військовим і ветеранам / Military & Veterans (slug ua-military)
--   * Банки / Banks (slug ua-banks)
--   * Платежі та комуналка / Payments & Utility Bills (slug ua-payments)
--   * Світло, газ і вода / Electricity, Gas & Water (slug ua-energy)
--   * Тривоги та безпека / Air Alerts & Safety (slug ua-alerts)
--   * Міські застосунки / City Apps (slug ua-city)
--   * Транспорт і квитки / Transport & Tickets (slug ua-transport)
--   * АЗС і водіям / Fuel & Drivers (slug ua-auto)
--   * Страхування / Insurance (slug ua-insurance)
--   * Пошта й доставка / Post & Delivery (slug ua-delivery)
--   * Покупки / Shopping (slug ua-shopping)
--   * Супермаркети / Supermarkets (slug ua-groceries)
--   * Медицина й аптеки / Healthcare & Pharmacies (slug ua-health)
--   * Зв'язок та інтернет / Mobile & Internet (slug ua-telecom)
--   * ТБ, новини та радіо / TV, News & Radio (slug ua-media)
--   * Книги та аудіокниги / Books & Audiobooks (slug ua-books)
--   * Освіта / Education (slug ua-education)
--   * Робота / Jobs (slug ua-jobs)
--   * Оголошення та нерухомість / Classifieds & Real Estate (slug ua-classifieds)
--   * Допомога та благодійність / Help & Charity (slug ua-charity)
--   * Для бізнесу та ФОП / Business & Sole Traders (slug ua-business)
-- + 34 нових продуктів (якщо продукт із такою адресою чи назвою вже є — лише прив'язка),
--   2 наявних лише прив'язано (тексти не змінюються): Freelancehunt, Kabanchik
-- Тексти UA/EN написано за офіційними описами застосунків в App Store (регіон UA), звірено 2026-10-28.
-- Ціни не вказано: план «Ціна: див. сайт» (0, one_time); Free — застосунок безкоштовний у магазині застосунків.
-- Категорія чутлива (categories.search_only_on_match = 1): це не АІ-інструменти, тож Еля пропонує їх лише на прямі запити
--   (банк, Дія, тривога, світло, пошта…); інтенти запасного пошуку Елі — у кінці файлу (tools/eli-intents.php).
-- Пропущено: АВТОЛЮКС і INFOBUS (застосунки іноземних компаній), Пузата Хата (неофіційний, російськомовний), Auchan (не українська мережа), Баночки (приватний розробник), РБК-Україна (неофіційний), Lviv Croissants (лише програма лояльності), Укрпошта 2.0 (Укрпошта вже є).
-- Без фіксованих id: @new рахується ДО INSERT, @pid — за нормалізованою адресою або назвою.
-- Застосування: phpMyAdmin → БД → «Импорт». Повторний запуск безпечний.
--   RealHelp — Допомога та благодійність
--   Волонтери Карітасу України — Допомога та благодійність
--   Я-ВПО — Допомога та благодійність, Державні послуги
--   Соціальні послуги Харківщини — Допомога та благодійність, Державні послуги
--   Твоє право — Державні послуги, Військовим і ветеранам, Допомога та благодійність
--   БЕЗ МЕЖ — Військовим і ветеранам
--   єППО — Тривоги та безпека, Військовим і ветеранам
--   Моя Податкова — Державні послуги, Для бізнесу та ФОП
--   Arsenal IC — Страхування, Медицина й аптеки
--   UNIVERSALNA Online — Страхування, Медицина й аптеки
--   VUSO Страхування — Страхування
--   hotline.finance — Страхування, АЗС і водіям
--   Робота Кабанчик — Робота
--   Delivery-Auto — Пошта й доставка
--   MAFIA — Пошта й доставка
--   LOKO — Пошта й доставка, Супермаркети
--   Flowers.ua — Пошта й доставка, Покупки
--   Велмарт — Супермаркети
--   Велика Кишеня — Супермаркети
--   ЕКО Маркет — Супермаркети
--   Близенько — Супермаркети, Пошта й доставка
--   МегаМаркет — Супермаркети
--   Будинок іграшок — Покупки
--   Нова Лінія — Покупки
--   1505 Черкаси — Міські застосунки
--   Mykolaiv Digital — Міські застосунки
--   Smart Chernihiv — Міські застосунки
--   Мій Кривий Ріг — Міські застосунки, Транспорт і квитки
--   Парковки Одеси — Міські застосунки, АЗС і водіям
--   Parking Dnipro — Міські застосунки, АЗС і водіям
--   lifecell TV — ТБ, новини та радіо, Зв'язок та інтернет
--   triolan.tv — Зв'язок та інтернет, ТБ, новини та радіо
--   Українське ТБ від Mediacast — ТБ, новини та радіо
--   Громадське радіо — ТБ, новини та радіо
--   Freelancehunt (наявний) — Робота
--   Kabanchik (наявний) — Оголошення та нерухомість, Робота
-- =====================================================================

SET @uid = (SELECT `id` FROM `users` WHERE `email` = 'whitevelvetelf@gmail.com' LIMIT 1);
SET @cat = (SELECT `id` FROM `categories` WHERE `slug` = 'ukrainian-apps' LIMIT 1);
SET @has_flag = (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'categories' AND COLUMN_NAME = 'search_only_on_match');
SET @sql = IF(@has_flag > 0 AND @cat IS NOT NULL, CONCAT('UPDATE `categories` SET `search_only_on_match` = 1 WHERE `id` = ', @cat), 'SELECT 1');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- RealHelp — Допомога та благодійність
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'realhelp.me' OR LOWER(`name`) = 'realhelp')), 1, 0);
